function notionId(value) {
  if (typeof value !== "string") throw Error("A Notion ID is missing.");
  const compact = value.replace(/-/g, "").toLowerCase();
  if (!/^[a-f0-9]{32}$/.test(compact)) throw Error("A Notion ID is invalid.");
  return compact.replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, "$1-$2-$3-$4-$5");
}

function checksForDate(config) {
  return {
    filter: { property: "Date", date: { equals: config.date } },
    sorts: [{ timestamp: "created_time", direction: "ascending" }],
    page_size: 100,
  };
}

function checkedPages(pages, config) {
  const ids = new Set();
  const pending = [];
  for (const page of pages) {
    const pageId = notionId(page?.id);
    if (
      page.object !== "page" ||
      page.archived === true ||
      page.in_trash === true ||
      page.parent?.type !== "data_source_id" ||
      notionId(page.parent.data_source_id) !== config.dataSource ||
      page.properties?.Date?.type !== "date" ||
      page.properties.Date.date?.start !== config.date ||
      page.properties.Date.date.end !== null ||
      page.properties?.Status?.type !== "select" ||
      !Number.isFinite(Date.parse(page.created_time)) ||
      ids.has(pageId)
    ) {
      throw Error("Notion returned an unexpected page for the configured date or data source.");
    }
    ids.add(pageId);
    if (page.properties.Status.select?.name !== "Published") {
      pending.push({
        pageId,
        created: page.created_time,
        key: "linkedin-notion-page:" + config.dataSource + ":" + pageId,
      });
    }
  }
  return pending.sort(
    (a, b) => a.created.localeCompare(b.created) || a.pageId.localeCompare(b.pageId),
  );
}

async function collectNotion(fetchPage, label) {
  const rows = [];
  const seen = new Set();
  let cursor;
  for (let index = 0; index < 10; index++) {
    const page = await fetchPage(cursor);
    if (
      !Array.isArray(page?.results) ||
      typeof page.has_more !== "boolean" ||
      page.results.length > 100 ||
      page.request_status?.type === "incomplete"
    ) {
      throw Error("Notion returned an invalid " + label + " list.");
    }
    rows.push(...page.results);
    if (page.has_more === false && page.next_cursor === null) return rows;
    if (
      !page.has_more ||
      typeof page.next_cursor !== "string" ||
      !page.next_cursor ||
      seen.has(page.next_cursor)
    ) {
      throw Error("Notion returned an incomplete " + label + " list.");
    }
    cursor = page.next_cursor;
    seen.add(cursor);
  }
  throw Error("Notion returned more than ten pages of " + label + ".");
}

export default async ({ config }, ctx) => {
  const { filter, sorts, page_size } = checksForDate(config);
  const rows = await collectNotion(
    (startCursor) =>
      ctx.actions.call("notion.query_data_source", {
        dataSourceId: config.dataSource,
        filter,
        sorts,
        pageSize: page_size,
        result_type: "page",
        ...(startCursor ? { startCursor } : {}),
      }),
    "scheduled posts",
  );
  return { rows: checkedPages(rows, config) };
};

