function checkMember(member, author) {
  if ("urn:li:person:" + member?.sub !== author)
    throw Error("LinkedIn authorization does not match the configured member.");
}

export default ({ member, tokenMember, config }) => {
  checkMember(member, config.author);
  checkMember(tokenMember, config.author);
  return { confirmed: true };
};

