export default async ({ rows, previous }, ctx) => {
  for (let i = (previous ?? -1) + 1; i < rows.length; i++) {
    if (!(await ctx.state.get(rows[i].key))) return { index: i, more: true, row: rows[i] };
  }
  return { index: rows.length, more: false, row: null };
};

