function hostedNotionImage(file) {
  const url = file?.url;
  const expires = Date.parse(file?.expiry_time);
  if (
    typeof url !== "string" ||
    url.length > 8000 ||
    !Number.isFinite(expires) ||
    expires <= Date.now() ||
    /[\s\\#]/.test(url) ||
    !/^https:\/\/(?:(?:prod-files-secure|secure\.notion-static\.com)\.s3(?:[.-][a-z0-9-]+)?\.amazonaws\.com\/[^?]+|s3(?:[.-][a-z0-9-]+)?\.amazonaws\.com\/(?:prod-files-secure|secure\.notion-static\.com)\/[^?]+)\?/i.test(
      url,
    )
  ) {
    throw Error("The first image must be an unexpired, Notion-hosted file URL.");
  }
  return url;
}

function notionPost(blocks, pageId) {
  const texts = [];
  const ids = new Set();
  let firstImage;
  for (const block of blocks) {
    const id = notionId(block?.id);
    if (
      block.object !== "block" ||
      block.parent?.type !== "page_id" ||
      notionId(block.parent.page_id) !== pageId ||
      ids.has(id) ||
      typeof block.type !== "string"
    ) {
      throw Error("Notion returned a block from a different page or repeated a block.");
    }
    ids.add(id);
    const data = block[block.type];
    if (block.type === "image" && data?.type === "file" && firstImage === undefined)
      firstImage = data.file;
    else if (
      ["child_page", "child_database"].includes(block.type) &&
      typeof data?.title === "string"
    )
      texts.push(data.title);
    else if (block.type !== "image") {
      const text = data?.rich_text ?? data?.text;
      if (Array.isArray(text))
        texts.push(text.map((part) => part?.plain_text ?? part?.text?.content ?? "").join(""));
    }
  }
  const text = texts
    .reduce(
      (combined, line, index) =>
        index ? combined + (line.startsWith("-") ? "\n\n" : "\n") + line : line,
      "",
    )
    .trim();
  if (!text || text.length > 3000)
    throw Error("Provide one to 3,000 characters of text in the post page.");
  return { text, imageUrl: hostedNotionImage(firstImage) };
}

async function collectNotion(fetchPage, label) {
  const rows = [];
  const seen = new Set();
  let cursor;
  for (let index = 0; index < 10; index++) {
    const page = await fetchPage(cursor);
    if (
      !Array.isArray(page?.results) ||
      typeof page.has_more !== "boolean" ||
      page.results.length > 100 ||
      page.request_status?.type === "incomplete"
    ) {
      throw Error("Notion returned an invalid " + label + " list.");
    }
    rows.push(...page.results);
    if (page.has_more === false && page.next_cursor === null) return rows;
    if (
      !page.has_more ||
      typeof page.next_cursor !== "string" ||
      !page.next_cursor ||
      seen.has(page.next_cursor)
    ) {
      throw Error("Notion returned an incomplete " + label + " list.");
    }
    cursor = page.next_cursor;
    seen.add(cursor);
  }
  throw Error("Notion returned more than ten pages of " + label + ".");
}

export default async ({ row, config }, ctx) => {
  const result = await collectNotion(
    (startCursor) =>
      ctx.actions.call("notion.list_block_children", {
        blockId: row.pageId,
        pageSize: 100,
        ...(startCursor ? { startCursor } : {}),
      }),
    "page blocks",
  );
  const { text, imageUrl } = notionPost(result, row.pageId);
  return { text, imageUrl, init: { initializeUploadRequest: { owner: config.author } } };
};

