function verifyBytes(bytes, mimeType) {
  const mime = typeof mimeType === "string" ? mimeType.split(";")[0].trim().toLowerCase() : "";
  const png = [137, 80, 78, 71, 13, 10, 26, 10].every((byte, index) => bytes[index] === byte);
  const jpeg = bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255;
  const gif =
    bytes[0] === 71 &&
    bytes[1] === 73 &&
    bytes[2] === 70 &&
    bytes[3] === 56 &&
    [55, 57].includes(bytes[4]) &&
    bytes[5] === 97;
  if (
    bytes.length < 16 ||
    bytes.length > 10 * 1024 * 1024 ||
    !(
      (mime === "image/png" && png) ||
      (mime === "image/jpeg" && jpeg) ||
      (mime === "image/gif" && gif)
    )
  ) {
    throw Error("The Notion file must be a JPEG, PNG, or GIF up to 10 MiB.");
  }
}

export default async ({ file, row }, ctx) => {
  verifyBytes(await ctx.artifact.open(file), file.mediaType);
  return {
    reserved: await ctx.state.insert(row.key, {
      status: "awaiting_publication_confirmation",
      pageId: row.pageId,
    }),
  };
};

