function imageUpload(body, status) {
  const value = body?.value;
  const image = value?.image;
  const url = value?.uploadUrl;
  const expiry = value?.uploadUrlExpiresAt;
  if (
    status !== 200 ||
    typeof image !== "string" ||
    !/^urn:li:image:[A-Za-z0-9_-]{1,150}$/.test(image) ||
    typeof url !== "string" ||
    !Number.isSafeInteger(expiry) ||
    expiry <= Date.now() ||
    /[\s#\\]/.test(url) ||
    !url.startsWith(
      "https://www.linkedin.com/dms-uploads/" +
        image.slice("urn:li:image:".length) +
        "/uploaded-image/0?",
    )
  ) {
    throw Error("LinkedIn did not confirm an upload slot for that image.");
  }
  return {
    image,
    uploadUrl: url,
    statusUrl: "https://api.linkedin.com/rest/images/" + encodeURIComponent(image),
  };
}

export default ({ body, status }) => imageUpload(body, status);

