function imageAvailable(body, status, image, author, count) {
  if (status !== 200 || body?.id !== image || body.owner !== author) {
    throw Error("LinkedIn did not confirm the same uploaded image and member.");
  }
  if (body.status === "AVAILABLE") return true;
  if (!["WAITING_UPLOAD", "PROCESSING"].includes(body.status) || count >= 10) {
    throw Error("LinkedIn did not finish processing the image. No post was attempted.");
  }
  return false;
}

function photoPost(author, commentary, image) {
  const text = commentary.replace(/[\\()[\]{}<>@|~_*]/gu, (character) => "\\" + character);
  return {
    author,
    commentary: text,
    visibility: "PUBLIC",
    lifecycleState: "PUBLISHED",
    distribution: {
      feedDistribution: "MAIN_FEED",
      targetEntities: [],
      thirdPartyDistributionChannels: [],
    },
    content: { media: { id: image } },
    isReshareDisabledByAuthor: false,
  };
}

export default ({ body, status, image, config, text }) => {
  imageAvailable(body, status, image, config.author, 10);
  return { post: photoPost(config.author, text, image) };
};

