function postReceipt(status, headers) {
  const postId = headers?.["x-restli-id"];
  if (
    status !== 201 ||
    typeof postId !== "string" ||
    !/^urn:li:(?:share|ugcPost):[1-9]\d*$/.test(postId)
  ) {
    throw Error(
      "LinkedIn did not confirm publication. Check the profile before clearing the reservation.",
    );
  }
  return postId;
}

export default async ({ status, headers, row }, ctx) => {
  const postId = postReceipt(status, headers);
  await ctx.state.set(row.key, { status: "post_confirmed", pageId: row.pageId, postId });
  return { postId, pageId: row.pageId };
};

