  if (!/^[a-f0-9]{32}$/.test(compact)) throw Error("A Notion ID is invalid.");
  return compact.replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, "$1-$2-$3-$4-$5");
}

function confirmNotion(page, pageId, dataSource) {
  if (
    page?.object !== "page" ||
    notionId(page?.id) !== pageId ||
    page.parent?.type !== "data_source_id" ||
    notionId(page.parent.data_source_id) !== dataSource ||
    page.properties?.Status?.select?.name !== "Published"
  ) {
    throw Error(
      "Notion did not confirm Published on the same page. The LinkedIn post must not be sent again.",
    );
  }
}

export default async ({ page, row, config, postId }, ctx) => {
  confirmNotion(page, row.pageId, config.dataSource);
  const result = { status: "published", pageId: row.pageId, postId };
  await ctx.state.set(row.key, result);
  return { result };
};
